## File: `components/appStack.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppStackConfig {
  environment: string;
  s3Versioning: boolean;
  dbInstanceClass: string;
  dbMultiAz: boolean;
  dbEncrypted: boolean;
}

export class AppStack extends pulumi.ComponentResource {
  public readonly bucketName: pulumi.Output<string>;
  public readonly bucketArn: pulumi.Output<string>;
  public readonly dbEndpoint: pulumi.Output<string>;
  public readonly dbName: pulumi.Output<string>;
  public readonly dbPort: pulumi.Output<number>;
  public readonly roleArn: pulumi.Output<string>;
  public readonly roleName: pulumi.Output<string>;
  public readonly dbSecretArn: pulumi.Output<string>;

  constructor(
    name: string,
    config: AppStackConfig,
    opts?: pulumi.ComponentResourceOptions
  ) {
    super("custom:infra:AppStack", name, {}, opts);

    const stack = pulumi.getStack();
    const projectName = pulumi.getProject();

    // ============ S3 Bucket ============
    const bucket = new aws.s3.Bucket(
      `${name}-bucket`,
      {
        bucket: `${projectName}-${config.environment}-bucket-${
          pulumi.automation?.getStack() ?? Date.now()
        }`.toLowerCase(),
        versioning: {
          enabled: config.s3Versioning,
        },
        serverSideEncryptionConfiguration: {
          rule: {
            applyServerSideEncryptionByDefault: {
              sseAlgorithm: "AES256",
            },
          },
        },
        tags: {
          Environment: config.environment,
          ManagedBy: "Pulumi",
        },
      },
      { parent: this }
    );

    // Block all public access to S3 bucket
    new aws.s3.BucketPublicAccessBlock(
      `${name}-bucket-pab`,
      {
        bucket: bucket.id,
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true,
      },
      { parent: this }
    );

    // ============ RDS PostgreSQL Instance ============

    // Get default VPC
    const defaultVpc = aws.ec2.getVpc({ default: true });

    // Get subnets in default VPC
    const subnetIds = pulumi
      .output(defaultVpc)
      .apply((vpc) =>
        aws.ec2.getSubnets({
          filters: [{ name: "vpc-id", values: [vpc.id] }],
        }).then((subnets) => subnets.ids)
      );

    // Create DB subnet group
    const subnetGroup = new aws.rds.SubnetGroup(
      `${name}-db-subnet-group`,
      {
        subnetIds: subnetIds,
        tags: {
          Environment: config.environment,
        },
      },
      { parent: this }
    );

    // Get default security group
    const defaultSecurityGroup = pulumi
      .output(defaultVpc)
      .apply((vpc) =>
        aws.ec2.getSecurityGroup({
          vpcId: vpc.id,
          name: "default",
        }).then((sg) => sg.id)
      );

    // Generate secure password
    const dbPassword = pulumi.secret(generateSecurePassword(32));

    // Create RDS PostgreSQL instance
    const database = new aws.rds.Instance(
      `${name}-db`,
      {
        identifier: `${projectName}-${config.environment}-db`.substring(0, 63),
        engine: "postgres",
        engineVersion: "15.3",
        instanceClass: config.dbInstanceClass,
        allocatedStorage: config.dbMultiAz ? 100 : 20,
        storageType: "gp3",
        dbName: "appdb",
        username: "postgres",
        password: dbPassword,
        multiAz: config.dbMultiAz,
        storageEncrypted: config.dbEncrypted,
        kmsKeyId: config.dbEncrypted
          ? new aws.kms.Key(
              `${name}-db-key`,
              {
                description: `KMS key for ${projectName} ${config.environment} RDS`,
                enableKeyRotation: true,
                deletionWindowInDays: 7,
              },
              { parent: this }
            ).arn
          : undefined,
        deletionProtection: true,
        backupRetentionPeriod: 7,
        backupWindow: "03:00-04:00",
        maintenanceWindow: "mon:04:00-mon:05:00",
        skipFinalSnapshot: false,
        finalSnapshotIdentifierPrefix: `${projectName}-${config.environment}-snapshot`,
        dbSubnetGroupName: subnetGroup.name,
        vpcSecurityGroupIds: [defaultSecurityGroup],
        publiclyAccessible: false,
        enableIamDatabaseAuthentication: true,
        tags: {
          Environment: config.environment,
          ManagedBy: "Pulumi",
        },
      },
      { parent: this }
    );

    // Store DB credentials in Secrets Manager
    const dbSecret = new aws.secretsmanager.Secret(
      `${name}-db-secret`,
      {
        name: `${projectName}/${config.environment}/db-credentials`,
        description: `Database credentials for ${projectName} ${config.environment}`,
        tags: {
          Environment: config.environment,
        },
      },
      { parent: this }
    );

    new aws.secretsmanager.SecretVersion(
      `${name}-db-secret-version`,
      {
        secretId: dbSecret.id,
        secretString: pulumi.all([dbPassword, database.endpoint]).apply(
          ([password, endpoint]) =>
            JSON.stringify({
              username: "postgres",
              password: password,
              engine: "postgres",
              host: endpoint.split(":")[0],
              port: 5432,
              dbname: "appdb",
            })
        ),
      },
      { parent: this }
    );

    // ============ IAM Role for Service Accounts ============

    const serviceRole = new aws.iam.Role(
      `${name}-service-role`,
      {
        name: `${projectName}-${config.environment}-service-role`.substring(
          0,
          64
        ),
        assumeRolePolicy: JSON.stringify({
          Version: "2012-10-17",
          Statement: [
            {
              Effect: "Allow",
              Principal: {
                Service: ["ec2.amazonaws.com", "ecs-tasks.amazonaws.com"],
              },
              Action: "sts:AssumeRole",
            },
          ],
        }),
        tags: {
          Environment: config.environment,
          ManagedBy: "Pulumi",
        },
      },
      { parent: this }
    );

    // S3 access policy (least privilege)
    new aws.iam.RolePolicy(
      `${name}-s3-policy`,
      {
        role: serviceRole.id,
        policy: bucket.arn.apply((arn) =>
          JSON.stringify({
            Version: "2012-10-17",
            Statement: [
              {
                Sid: "ListBucket",
                Effect: "Allow",
                Action: ["s3:ListBucket", "s3:GetBucketVersioning"],
                Resource: arn,
              },
              {
                Sid: "ObjectAccess",
                Effect: "Allow",
                Action: ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"],
                Resource: `${arn}/*`,
              },
            ],
          })
        ),
      },
      { parent: this }
    );

    // RDS access policy (least privilege - no wildcard)
    new aws.iam.RolePolicy(
      `${name}-rds-policy`,
      {
        role: serviceRole.id,
        policy: database.arn.apply((dbArn) =>
          JSON.stringify({
            Version: "2012-10-17",
            Statement: [
              {
                Sid: "DescribeDB",
                Effect: "Allow",
                Action: ["rds:DescribeDBInstances"],
                Resource: dbArn,
              },
              {
                Sid: "IAMDatabaseAuth",
                Effect: "Allow",
                Action: ["rds-db:connect"],
                Resource: `${dbArn}/*`,
              },
            ],
          })
        ),
      },
      { parent: this }
    );

    // Secrets Manager access (retrieve DB credentials)
    new aws.iam.RolePolicy(
      `${name}-secrets-policy`,
      {
        role: serviceRole.id,
        policy: dbSecret.arn.apply((secretArn) =>
          JSON.stringify({
            Version: "2012-10-17",
            Statement: [
              {
                Sid: "GetDatabaseSecret",
                Effect: "Allow",
                Action: [
                  "secretsmanager:GetSecretValue",
                  "secretsmanager:DescribeSecret",
                ],
                Resource: secretArn,
              },
            ],
          })
        ),
      },
      { parent: this }
    );

    // Register outputs
    this.bucketName = bucket.id;
    this.bucketArn = bucket.arn;
    this.dbEndpoint = database.endpoint;
    this.dbName = database.dbName;
    this.dbPort = database.port;
    this.roleArn = serviceRole.arn;
    this.roleName = serviceRole.name;
    this.dbSecretArn = dbSecret.arn;

    this.registerOutputs({
      bucketName: this.bucketName,
      bucketArn: this.bucketArn,
      dbEndpoint: this.dbEndpoint,
      dbName: this.dbName,
      dbPort: this.dbPort,
      roleArn: this.roleArn,
      roleName: this.roleName,
      dbSecretArn: this.dbSecretArn,
    });
  }
}

/**
 * Generate a cryptographically secure random password.
 */
function generateSecurePassword(length: number): string {
  const chars =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:,.<>?";
  let password = "";
  for (let i = 0; i < length; i++) {
    password += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return password;
}
```

## File: `index.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import { AppStack } from "./components/appStack";

const config = new pulumi.Config();

// Require environment setting
const environment = config.require("environment");

// Database instance class (required)
const dbInstanceClass = config.require("dbInstanceClass");

// Optional settings with defaults
const s3Versioning = config.getBoolean("s3Versioning") ?? true;
const dbMultiAz = config.getBoolean("dbMultiAz") ?? environment === "prod";
const dbEncrypted = config.getBoolean("dbEncrypted") ?? true;

// Create the application infrastructure stack
const appStack = new AppStack("app", {
  environment,
  s3Versioning,
  dbInstanceClass,
  dbMultiAz,
  dbEncrypted,
});

// Export key outputs for cross-stack references
export const bucketName = appStack.bucketName;
export const bucketArn = appStack.bucketArn;
export const dbEndpoint = appStack.dbEndpoint;
export const dbName = appStack.dbName;
export const dbPort = appStack.dbPort;
export const roleArn = appStack.roleArn;
export const roleName = appStack.roleName;
export const dbSecretArn = appStack.dbSecretArn;
```

